import React, { useEffect, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../App.css";

const Checkout = () => {
  const { state } = useLocation();
  const navigate = useNavigate();
  const cartItems = state?.cartItems || [];
  const subtotal = state?.subtotal || 0;
  const userId = sessionStorage.getItem("userId");

  const [shipping, setShipping] = useState({
    fullName: "",
    email: "",
    address1: "",
    address2: "",
    city: "",
    state: "",
    zip: "",
    country: ""
  });

  // Fetch user profile to autofill shipping info
  useEffect(() => {
    const fetchUser = async () => {
      try {
        const res = await fetch(`${API_BASE_URL}/api/users/${userId}`);
        const user = await res.json();

        setShipping({
          fullName: user.name || user.username || "",
          email: user.email || "",
          address1: user.shipping_address1 || "",
          address2: user.shipping_address2 || "",
          city: user.shipping_city || "",
          state: user.shipping_state || "",
          zip: user.shipping_zip || "",
          country: user.shipping_country || "USA"
        });
      } catch (err) {
        console.error("Failed to load user shipping info:", err);
      }
    };

    fetchUser();
  }, [userId]);

  const handleChange = (e) => {
    setShipping({ ...shipping, [e.target.name]: e.target.value });
  };

  const isValidForm = () => {
    const { fullName, email, address1, city, state, zip, country } = shipping;
    return fullName && email && address1 && city && state && zip && country;
  };

  const handlePlaceOrder = async () => {
    if (!isValidForm()) {
      alert("⚠️ Please complete all required shipping fields.");
      return;
    }
  
    const buyer_name = shipping.fullName;
    const buyer_email = shipping.email;
    const buyer_phone = shipping.phone || ""; // Optional
  
    try {
      const res = await fetch(`${API_BASE_URL}/api/orders`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          user_id: userId,
          items: cartItems.map((item) => ({
            listing_id: item.listing_id, // ✅ no fallback — we only want the real listing_id
            seller_id: item.user_id,      // <- required by your backend
            price: parseFloat(item.price),

          })),
          
          total: subtotal,
          shipping_info: shipping,
          buyer_name,
          buyer_email,
          buyer_phone,
        }),
      });
  
      if (res.ok) {
        await fetch(`${API_BASE_URL}/api/cart/clear/${userId}`, {
          method: "DELETE",
        });
  
        alert("✅ Order placed successfully!");
        navigate("/my-orders");
      } else {
        const error = await res.json();
        alert("❌ Order failed: " + error.details);
      }
    } catch (err) {
      console.error("Order error:", err);
      alert("Something went wrong.");
    }
  };
  

  return (
    <div className="dashboard-wrapper">
      <Navbar />
      <main className="checkout-container">
        <h2>Checkout</h2>

        <div className="checkout-wrapper">
          {/* Shipping Info */}
          <div className="checkout-section">
            <h3>Shipping Information</h3>
            <form className="checkout-form">
              <input
                name="fullName"
                value={shipping.fullName}
                onChange={handleChange}
                placeholder="Full Name"
                required
              />
              <input
                name="email"
                value={shipping.email}
                onChange={handleChange}
                placeholder="Email Address"
                required
              />
              <input
                name="address1"
                value={shipping.address1}
                onChange={handleChange}
                placeholder="Address Line 1"
                required
              />
              <input
                name="address2"
                value={shipping.address2}
                onChange={handleChange}
                placeholder="Address Line 2"
              />
              <input
                name="city"
                value={shipping.city}
                onChange={handleChange}
                placeholder="City"
                required
              />
              <input
                name="state"
                value={shipping.state}
                onChange={handleChange}
                placeholder="State"
                required
              />
              <input
                name="zip"
                value={shipping.zip}
                onChange={handleChange}
                placeholder="Zip Code"
                required
              />
              <input
                name="country"
                value={shipping.country}
                onChange={handleChange}
                placeholder="Country"
                required
              />
            </form>
          </div>

          {/* Payment Summary */}
          <div className="checkout-summary">
            <h3>Payment Summary</h3>
            <p><strong>Subtotal:</strong> ${subtotal.toFixed(2)}</p>
            <p><strong>Delivery:</strong> FREE</p>
            <p><strong>Total:</strong> ${subtotal.toFixed(2)}</p>

            <button className="checkout-btn" onClick={handlePlaceOrder}>
              Place Order
            </button>
            <p className="secure-text">🔒 Secure Payment</p>
          </div>
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default Checkout;
